import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, Renderer2 } from '@angular/core';
import { Router } from '@angular/router';
import { finalize, takeUntil } from 'rxjs/operators';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BroadcastingService, roundNumber, TaxesService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { MessageService } from '@honoregaming/ui';
import { WithdrawProvider } from 'projects/customer/hg-account/src/lib/models/withdraw-provider.model';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import {
  GenericTransactionResponse,
  PaymentProviderValidationType
} from '../../models/generic-transaction-response.model';
import { CustomerWithdrawalInformations } from '../../models/customer-withdrawal-informations.model';
import { OperationConfirmationType } from '../../enums/operation-confirmation-type.enum';
import { WithdrawProviderBaseComponent } from '../../provider-base';

@Component({
  selector: 'hg-withdraw-provider',
  templateUrl: './withdraw-provider.component.html',
  styleUrls: ['./withdraw-provider.component.scss', '../../provider-base/provider-base.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawProviderComponent extends WithdrawProviderBaseComponent implements OnInit, WithdrawProvider {
  cgu: boolean = false;
  operationRef?: string;

  constructor(
    protected readonly accountService: AccountService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  get canSubmit(): boolean {
    return this.isValid && !this.loading && this.cgu;
  }

  submitWithdraw(): void {
    this.loading = true;
    this.failure = null;

    this.accountService
      .createWithdraw(
        this.provider,
        roundNumber(this.amount, this.numberOfDecimals),
        this.selectedInnerProvider,
        null,
        { useDifferentAccount: false } as CustomerWithdrawalInformations
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          const iframe: HTMLIFrameElement = document.createElement('iframe');
          iframe.setAttribute('id', 'niubiz');
          iframe.src = 'about:blank';
          iframe.style.position = 'fixed';
          iframe.style.top = '0';
          iframe.style.left = '0';
          iframe.style.right = '0';
          iframe.style.bottom = '0';
          iframe.style.margin = 'auto';
          iframe.style.width = '100%';
          iframe.style.height = '100%';
          iframe.style.zIndex = '9999';

          iframe.addEventListener('load', () => {
            const iframeDocument: Document = iframe.contentDocument;
            iframe.contentWindow.window['retrieveInformations'] = _ => {
              this.submitWithdrawalConfirmation((iframeDocument.getElementsByName('transactionToken')[0] as any).value);
            };

            const visanetCheckoutScript: HTMLScriptElement = iframeDocument.createElement('script');
            visanetCheckoutScript.src = response.value['NiubizScriptUrl'];
            visanetCheckoutScript.type = 'application/javascript';
            visanetCheckoutScript.async = false;

            visanetCheckoutScript.onload = () => {
              const visanetCheckout = iframe.contentWindow['VisanetCheckout'];

              if (visanetCheckout) {
                this.step = PaymentProviderValidationType[response.validationType];
                this.cdRef.markForCheck();
                this.operationRef = response.value['PurchaseNumber'];

                visanetCheckout.configure({
                  action: 'javascript:void(0); retrieveInformations();',
                  sessiontoken: response.value['SessionToken'],
                  channel: response.value['Channel'],
                  merchantid: response.value['MerchantId'],
                  purchasenumber: this.operationRef,
                  amount: response.value['Amount'],
                  usertoken: response.value['UserToken'],
                  expirationminutes: response.value['ExpirationMinutes'],
                  cardholdername: response.value['CustomerFirstName'],
                  cardholderlastname: response.value['CustomerLastName'],
                  cardholderemail: response.value['CustomerEmail'],
                  timeouturl: response.value['TimeoutUrl'],
                  merchantlogo: response.value['MerchantLogo'],
                  merchantname: response.value['MerchantName'],
                  formbuttoncolor: response.value['FormButtonColor'],
                  formbuttontext: this.i18nService.translateSync(response.value['FormButtonText']),
                  showamount: response.value['ShowAmount'],
                  cancel: _ => {
                    this.step = 1;
                    this.amount = 0;
                    this.cgu = false;
                    this.failure = 'CONTACT_SUPPORT';
                    this.cdRef.markForCheck();
                  }
                });

                const niubizIframe: any = iframeDocument.querySelector('#visaNetJS');
                niubizIframe.style.background = 'rgba(0, 0, 0, 0.6)';
                niubizIframe.style.display = 'block';

                visanetCheckout.open();
              }
            };

            iframeDocument.head.appendChild(visanetCheckoutScript);
          });

          document.body.appendChild(iframe);
        },
        (error: unknown) => {
          this.handleWithdrawError(error);
        }
      );
  }

  private submitWithdrawalConfirmation(token: string): void {
    if (!this.operationRef) {
      return;
    }

    const iframe: any = document.querySelector('#niubiz');
    iframe.remove();

    this.failure = null;

    this.accountService
      .confirmWithdrawal(
        this.provider,
        this.operationRef,
        OperationConfirmationType.Token,
        { token: token },
        this.selectedInnerProvider
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.step = PaymentProviderValidationType[response.validationType];
          this.submitted = true;
          this.bcService.broadcast('payment-provider-scroll-to-top');
          this.withdrawSuccess.emit();
        },
        (error: unknown) => {
          this.handleWithdrawError(error);
          this.step = 1;
        }
      );
  }
}
