import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Renderer2,
  Inject,
  ChangeDetectorRef,
  OnDestroy
} from '@angular/core';
import { Router } from '@angular/router';
import { finalize, takeUntil } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { roundNumber, BroadcastingService, TaxesService } from '@honoregaming/core';
import { OperationStatus, SecurityPolicy } from '@honoregaming/types';
import { AuthService } from '@honoregaming/customer-core';
import { MessageService } from '@honoregaming/ui';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { DepositProvider } from 'projects/customer/hg-account/src/lib/models/deposit-provider.model';
import { OperationType } from 'projects/customer/hg-account/src/lib/models/operation.model';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import {
  GenericTransactionResponse,
  PaymentProviderValidationType
} from '../../models/generic-transaction-response.model';
import { OperationConfirmationType } from '../../enums/operation-confirmation-type.enum';
import { DepositProviderBaseComponent } from '../../provider-base';

@Component({
  selector: 'hg-deposit-provider',
  templateUrl: './deposit-provider.component.html',
  styleUrls: ['./deposit-provider.component.scss', '../../provider-base/provider-base.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositProviderComponent
  extends DepositProviderBaseComponent
  implements OnInit, OnDestroy, DepositProvider
{
  cgu: boolean = false;
  securityPolicy?: SecurityPolicy;

  OperationStatus = OperationStatus;
  operationRef: string | null = null;
  operationStatus?: OperationStatus;
  operationDescription?: string;
  operationLocalDateTime?: string;
  operationAmount?: number;
  operationCard?: string;
  operationCurrency?: string;
  operationBrand?: string;

  private depositTimeoutId: number | null = null;

  OperationType = OperationType;

  constructor(
    protected readonly authService: AuthService,
    protected readonly accountService: AccountService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  get canSubmit(): boolean {
    return this.isValid && !this.loading && this.cgu;
  }

  submitDeposit(): void {
    this.loading = true;
    this.failure = null;

    this.accountService
      .createDeposit(this.provider, roundNumber(this.amount, this.numberOfDecimals), null, this.selectedInnerProvider)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.handleDepositSuccess(response);
        },
        (error: unknown) => {
          this.handleDepositError(error);
          this.loading = false;
          this.removeNiubizIframe();
        }
      );
  }

  private submitDepositConfirmation(token: string): void {
    if (!this.operationRef) {
      return;
    }

    this.clearDepositTimeout();
    this.removeNiubizIframe();
    this.failure = null;

    this.accountService
      .confirmDeposit(
        this.provider,
        this.operationRef,
        OperationConfirmationType.Token,
        { token },
        this.selectedInnerProvider
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.applyConfirmationResponse(response);
        },
        (error: unknown) => {
          this.handleDepositError(error);
          this.step = 1;
        }
      );
  }

  private handleDepositSuccess(response: GenericTransactionResponse): void {
    const iframe: HTMLIFrameElement = this.createNiubizIframe();

    iframe.addEventListener('load', () => {
      this.initializeVisanetCheckout(iframe, response);
    });

    document.body.appendChild(iframe);
  }

  private createNiubizIframe(): HTMLIFrameElement {
    const iframe: HTMLIFrameElement = document.createElement('iframe');
    iframe.setAttribute('id', 'niubiz');
    iframe.src = 'about:blank';

    Object.assign(iframe.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      margin: 'auto',
      width: '100%',
      height: '100%',
      zIndex: '9999'
    });

    return iframe;
  }

  private initializeVisanetCheckout(iframe: HTMLIFrameElement, response: GenericTransactionResponse): void {
    const iframeDocument: Document | null = iframe.contentDocument;

    if (!iframeDocument || !iframe.contentWindow) {
      return;
    }

    iframe.contentWindow.window['retrieveInformations'] = () => {
      const tokenInput: HTMLInputElement | null = iframeDocument.getElementsByName(
        'transactionToken'
      )[0] as HTMLInputElement;

      if (tokenInput) {
        this.submitDepositConfirmation(tokenInput.value);
      }
    };

    const visanetScript: HTMLScriptElement = iframeDocument.createElement('script');
    visanetScript.src = response.value['NiubizScriptUrl'];
    visanetScript.type = 'application/javascript';
    visanetScript.async = false;

    visanetScript.onload = () => {
      this.onVisanetScriptLoaded(iframe, response);
    };

    iframeDocument.head.appendChild(visanetScript);
  }

  private onVisanetScriptLoaded(iframe: HTMLIFrameElement, response: GenericTransactionResponse): void {
    const visanetCheckout: Record<string, Function> | undefined = iframe.contentWindow?.['VisanetCheckout'];

    if (!visanetCheckout) {
      return;
    }

    this.step = PaymentProviderValidationType[response.validationType];
    this.cdRef.markForCheck();
    this.operationRef = response.value['PurchaseNumber'];

    visanetCheckout['configure'](this.buildVisanetConfig(response));

    const niubizInnerIframe: HTMLElement | null = iframe.contentDocument?.querySelector('#visaNetJS') ?? null;

    if (niubizInnerIframe) {
      niubizInnerIframe.style.background = 'rgba(0, 0, 0, 0)';
      niubizInnerIframe.style.display = 'block';
    }

    visanetCheckout['open']();
  }

  private buildVisanetConfig(response: GenericTransactionResponse): Record<string, unknown> {
    return {
      action: 'javascript:void(0); retrieveInformations();',
      sessiontoken: response.value['SessionToken'],
      channel: response.value['Channel'],
      merchantid: response.value['MerchantId'],
      purchasenumber: this.operationRef,
      amount: response.value['Amount'],
      usertoken: response.value['UserToken'],
      expirationminutes: response.value['ExpirationMinutes'],
      cardholdername: response.value['CustomerFirstName'],
      cardholderlastname: response.value['CustomerLastName'],
      cardholderemail: response.value['CustomerEmail'],
      timeouturl: response.value['TimeoutUrl'],
      merchantlogo: response.value['MerchantLogo'],
      merchantname: response.value['MerchantName'],
      formbuttoncolor: response.value['FormButtonColor'],
      formbuttontext: this.i18nService.translateSync(response.value['FormButtonText']),
      showamount: response.value['ShowAmount'],
      cancel: () => {
        this.handleVisanetCancel();
      }
    };
  }

  private handleVisanetCancel(): void {
    this.depositTimeoutId = window.setTimeout(() => {
      this.removeNiubizIframe();
      this.failure = null;
      this.step = 1;
      this.loading = false;
      this.cgu = false;
      this.amount = null;
      this.operationRef = null;
      this.cdRef.markForCheck();
    }, 5000);
  }

  private applyConfirmationResponse(response: GenericTransactionResponse): void {
    this.step = PaymentProviderValidationType[response.validationType];
    this.operationDescription = response.value['Description'];
    this.operationRef = response.value['OperationRef'];
    this.operationLocalDateTime = response.value['DateTime'];
    this.operationAmount = response.value['Amount'];
    this.operationCard = response.value['Card'];
    this.operationCurrency = response.value['Currency'];
    this.operationStatus = OperationStatus[response.value['OperationStatus']];
    this.operationBrand = response.value['Brand'];
    this.submitted = true;
    this.bcService.broadcast('payment-provider-scroll-to-top');
    this.depositSuccess.emit();
  }

  private removeNiubizIframe(): void {
    const iframe: HTMLIFrameElement | null = document.querySelector('#niubiz');
    iframe?.remove();
  }

  private clearDepositTimeout(): void {
    if (this.depositTimeoutId !== null) {
      clearTimeout(this.depositTimeoutId);
      this.depositTimeoutId = null;
    }
  }
}
