import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DepositProviderComponent } from './deposit-provider/deposit-provider.component';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { HgI18nModule } from '@honoregaming/i18n';
import { HgTemplatingModule } from '@honoregaming/templating';
import { HgUiModule } from '@honoregaming/ui';
import { WithdrawProviderComponent } from './withdraw-provider/withdraw-provider.component';

@NgModule({
  declarations: [DepositProviderComponent, WithdrawProviderComponent],
  imports: [CommonModule, HgI18nModule, HgUiModule, RouterModule, FormsModule, HgTemplatingModule]
})
export class NiubizModule {
  static deposit = DepositProviderComponent;
  static withdraw = WithdrawProviderComponent;
}
